export function solitaireLeaders(entries){const members=new Map();for(const r of Array.isArray(entries)?entries:[]){if(!r||typeof r.userId!=='string'||!r.userId||typeof r.name!=='string'||!r.name.trim()||!Number.isSafeInteger(r.score)||r.score<0||r.score>1245||!Number.isSafeInteger(r.elapsedMs)||r.elapsedMs<1000||r.elapsedMs>86400000||!Number.isFinite(r.at))continue;const old=members.get(r.userId);if(!old||compare(r,old)<0)members.set(r.userId,r);}return[...members.values()].sort(compare).slice(0,30);}
