 async function ranking(){const id=++requestId;try{const{data,error}=await db.rpc('get_solitaire_leaderboard');if(!alive()||id!==requestId)return;if(error||!data)throw Error();rankingView(data.entries);if(Number.isFinite(data.resetsAt)&&Number.isFinite(data.serverNow)&&data.resetsAt>data.serverNow){monthDeadline=Date.now()+data.resetsAt-data.serverNow;armMonth();}}catch{if(alive()&&id===requestId){$('#sol-empty').hidden=false;$('#sol-empty').textContent='랭킹을 불러오지 못했어요. 잠시 뒤 다시 확인해 주세요.';}}}
